class Solution {
public:
    vector<int> arrayChange(vector<int>& nums, vector<vector<int>>& operations) {
        unordered_map<int, int> dest;
        for (int i = operations.size() - 1; i >= 0; i--) {
            int a = operations[i][0], b = operations[i][1];
            auto it = dest.find(b);
            dest[a] = (it == dest.end()) ? b : it->second;
        }
        for (int& v : nums) {
            auto it = dest.find(v);
            if (it != dest.end()) v = it->second;
        }
        return nums;
    }
};

